// React example: use previous state, not a stale captured number
function Counter() {
  const [count, setCount] = React.useState(0);
  function addLater() {
    setTimeout(() => {
      setCount(prev => prev + 1);
    }, 1000);
  }
  return <button onClick={addLater}>{count}</button>;
}

